const req = $('Params').all(); const items = $input.all(); const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const s = req[i].json;
  out.push({ json: { body: { screenshots: [{ data: 'data:image/png;base64,' + buf.toString('base64'), title: s.title, description: 'LQA screenshot from dev /es/ before the fix (IQTST-1025, Jira attachment). The highlighted English text on the Spanish page is what these keys now translate.', ocr: false, key_ids: s.keys, tags: ['IQTST-1025'] }] }, title: s.title, keys: s.keys } });
}
return out;

const sent = $('Build').all(); const res = $input.all(); const rows = []; const bad = [];
for (let i = 0; i < res.length; i++) {
  const sc = (res[i].json.screenshots || [])[0];
  if (!sc) { bad.push({ title: sent[i].json.title, resp: JSON.stringify(res[i].json).slice(0, 300) }); continue; }
  const want = sent[i].json.keys.slice().sort().join(','); const got = (sc.key_ids || []).slice().sort().join(',');
  rows.push({ id: sc.screenshot_id, title: sc.title, keys_match: want === got });
  if (want !== got) { bad.push({ title: sc.title, want: want, got: got }); }
}
return [{ json: { uploaded: rows.length, rows: rows, problems: bad } }];
